INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (30,1,25,71,71,'[71, 80, 82]',556,'Damit besitzt eine Abbildung dieselbe grundlegende Eindeutigkeitsforderung wie eine Funktion. In der mathematischen Literatur werden beide Begriffe häufig synonym verwendet, wobei der Begriff *Abbildung* insbesondere dann verwendet wird, wenn die Wirkung auf mathematische Strukturen untersucht wird \\[71, 80, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (31,1,25,80,80,'[71, 80, 82]',556,'Damit besitzt eine Abbildung dieselbe grundlegende Eindeutigkeitsforderung wie eine Funktion. In der mathematischen Literatur werden beide Begriffe häufig synonym verwendet, wobei der Begriff *Abbildung* insbesondere dann verwendet wird, wenn die Wirkung auf mathematische Strukturen untersucht wird \\[71, 80, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (32,1,25,82,82,'[71, 80, 82]',556,'Damit besitzt eine Abbildung dieselbe grundlegende Eindeutigkeitsforderung wie eine Funktion. In der mathematischen Literatur werden beide Begriffe häufig synonym verwendet, wobei der Begriff *Abbildung* insbesondere dann verwendet wird, wenn die Wirkung auf mathematische Strukturen untersucht wird \\[71, 80, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (33,1,25,71,71,'[71, 82]',558,'Die Abbildung selbst enthält zunächst keine Aussage darüber, ob geometrische, algebraische oder analytische Eigenschaften erhalten bleiben. Solche Eigenschaften ergeben sich erst aus zusätzlichen Bedingungen an die Abbildung \\[71, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (34,1,25,82,82,'[71, 82]',558,'Die Abbildung selbst enthält zunächst keine Aussage darüber, ob geometrische, algebraische oder analytische Eigenschaften erhalten bleiben. Solche Eigenschaften ergeben sich erst aus zusätzlichen Bedingungen an die Abbildung \\[71, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (35,1,25,71,71,'[71, 82, 10]',562,'Besitzen Definitions- und Zielmenge zusätzliche algebraische Strukturen, kann ich untersuchen, ob diese unter der Abbildung erhalten bleiben. Für Vektorräume betrifft dies insbesondere die Addition von Vektoren und die Multiplikation mit Skalaren. Abbildungen, welche diese Operationen respektieren, bilden den Gegenstand der linearen Algebra \\[71, 82, 10\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (36,1,25,82,82,'[71, 82, 10]',562,'Besitzen Definitions- und Zielmenge zusätzliche algebraische Strukturen, kann ich untersuchen, ob diese unter der Abbildung erhalten bleiben. Für Vektorräume betrifft dies insbesondere die Addition von Vektoren und die Multiplikation mit Skalaren. Abbildungen, welche diese Operationen respektieren, bilden den Gegenstand der linearen Algebra \\[71, 82, 10\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (37,1,25,NULL,10,'[71, 82, 10]',562,'Besitzen Definitions- und Zielmenge zusätzliche algebraische Strukturen, kann ich untersuchen, ob diese unter der Abbildung erhalten bleiben. Für Vektorräume betrifft dies insbesondere die Addition von Vektoren und die Multiplikation mit Skalaren. Abbildungen, welche diese Operationen respektieren, bilden den Gegenstand der linearen Algebra \\[71, 82, 10\\].','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (38,1,25,71,71,'[71, 82, 10]',583,'Erst wenn beide Bedingungen erfüllt sind, handelt es sich um eine lineare Abbildung. Beide Bedingungen bilden gemeinsam die mathematische Definition der Linearität \\[71, 82, 10\\]. Im Original wurden Additivität und Homogenität getrennt als Gleichungen (3.61) und (3.62) geführt; fachlich gehören sie jedoch unmittelbar zusammen.','resolved');
