INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (41,1,25,82,82,'[82, 13]',593,'Ein Operator wirkt somit innerhalb desselben Vektorraums. Er erzeugt keinen neuen mathematischen Raum, sondern verändert ausschließlich Elemente eines bereits festgelegten Zustandsraums. Diese Definition wird in der linearen Algebra ebenso verwendet wie in der Funktionalanalysis \\[82, 13\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (42,1,25,NULL,13,'[82, 13]',593,'Ein Operator wirkt somit innerhalb desselben Vektorraums. Er erzeugt keinen neuen mathematischen Raum, sondern verändert ausschließlich Elemente eines bereits festgelegten Zustandsraums. Diese Definition wird in der linearen Algebra ebenso verwendet wie in der Funktionalanalysis \\[82, 13\\].','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (43,1,25,82,82,'[82, 13]',595,'Die Bezeichnung *Operator* beschreibt dabei keine besondere Rechenvorschrift. Sie charakterisiert zunächst die Tatsache, dass Definitions- und Zielraum identisch sind \\[82, 13\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (44,1,25,NULL,13,'[82, 13]',595,'Die Bezeichnung *Operator* beschreibt dabei keine besondere Rechenvorschrift. Sie charakterisiert zunächst die Tatsache, dass Definitions- und Zielraum identisch sind \\[82, 13\\].','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (45,1,25,71,71,'[71, 82, 13]',616,'Operatoren bilden somit im Allgemeinen keine kommutative Struktur. Ihre Verkettung ist dagegen assoziativ, sodass ich längere Operatorfolgen eindeutig zusammenfassen kann \\[71, 82, 13\\]. Der ursprüngliche Abschnitt führte die beiden Operatorsignaturen, die Verkettung und deren Wirkung noch als vier eigenständige Gleichungen (3.64)--(3.67); diese künstliche Aufspaltung wird hier beseitigt.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (46,1,25,82,82,'[71, 82, 13]',616,'Operatoren bilden somit im Allgemeinen keine kommutative Struktur. Ihre Verkettung ist dagegen assoziativ, sodass ich längere Operatorfolgen eindeutig zusammenfassen kann \\[71, 82, 13\\]. Der ursprüngliche Abschnitt führte die beiden Operatorsignaturen, die Verkettung und deren Wirkung noch als vier eigenständige Gleichungen (3.64)--(3.67); diese künstliche Aufspaltung wird hier beseitigt.','resolved');
