INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (48,1,25,82,82,'[82, 13]',626,'Der Identitätsoperator verändert keinen Vektor und bildet das neutrale Element bezüglich der Operatorverkettung \\[82, 13\\]. Deshalb gilt für jeden passenden Operator $T$','resolved');
