INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (51,1,25,82,82,'[71, 82]',630,'Diese Eigenschaft entspricht der Rolle eines neutralen Elements in algebraischen Strukturen \\[71, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (52,1,25,82,82,'[82, 13]',646,'Invertierbare Operatoren ermöglichen eine eindeutige Rückführung transformierter Zustände auf ihren Ausgangszustand. Existiert eine solche Umkehrung nicht, können verschiedene Zustände auf denselben Zielzustand abgebildet werden beziehungsweise bei der Transformation Informationen für eine eindeutige Rekonstruktion verloren gehen \\[82, 13\\]. Im Original wurden $T^{- 1}$ und die beiden Inversenbedingungen getrennt als Gleichungen (3.72)--(3.74) geführt; dies wird hier als zusammengehörende mathematische Aussage behandelt.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (53,1,25,NULL,13,'[82, 13]',646,'Invertierbare Operatoren ermöglichen eine eindeutige Rückführung transformierter Zustände auf ihren Ausgangszustand. Existiert eine solche Umkehrung nicht, können verschiedene Zustände auf denselben Zielzustand abgebildet werden beziehungsweise bei der Transformation Informationen für eine eindeutige Rekonstruktion verloren gehen \\[82, 13\\]. Im Original wurden $T^{- 1}$ und die beiden Inversenbedingungen getrennt als Gleichungen (3.72)--(3.74) geführt; dies wird hier als zusammengehörende mathematische Aussage behandelt.','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (54,1,25,NULL,10,'[10, 82]',650,'Für endlichdimensionale Vektorräume kann jeder lineare Operator bezüglich einer gewählten Basis durch eine Matrix dargestellt werden. Die Matrix beschreibt dabei nicht den Operator selbst, sondern dessen Darstellung relativ zu einer konkreten Basis. Ändert sich die Basis, so ändert sich im Allgemeinen auch die Matrixdarstellung, während der zugrunde liegende Operator unverändert bleibt \\[10, 82\\].','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (55,1,25,82,82,'[10, 82]',650,'Für endlichdimensionale Vektorräume kann jeder lineare Operator bezüglich einer gewählten Basis durch eine Matrix dargestellt werden. Die Matrix beschreibt dabei nicht den Operator selbst, sondern dessen Darstellung relativ zu einer konkreten Basis. Ändert sich die Basis, so ändert sich im Allgemeinen auch die Matrixdarstellung, während der zugrunde liegende Operator unverändert bleibt \\[10, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (56,1,25,NULL,10,'[10, 82]',666,'Die Matrixmultiplikation beschreibt damit die Wirkung des Operators auf den dargestellten Vektor. Die geometrische oder physikalische Interpretation dieser Wirkung hängt jedoch vom jeweiligen Anwendungsgebiet ab und folgt nicht aus der Matrixdarstellung selbst \\[10, 82\\].','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (57,1,25,82,82,'[10, 82]',666,'Die Matrixmultiplikation beschreibt damit die Wirkung des Operators auf den dargestellten Vektor. Die geometrische oder physikalische Interpretation dieser Wirkung hängt jedoch vom jeweiligen Anwendungsgebiet ab und folgt nicht aus der Matrixdarstellung selbst \\[10, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (58,1,25,NULL,10,'[10, 82]',670,'Ein Eigenvektor eines Operators ist ein von Null verschiedener Vektor, dessen Richtungslinie unter der Wirkung des Operators erhalten bleibt. Der Operator verändert ihn lediglich durch Multiplikation mit einem Skalar, dem zugehörigen Eigenwert \\[10, 82\\].','unresolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (59,1,25,82,82,'[10, 82]',670,'Ein Eigenvektor eines Operators ist ein von Null verschiedener Vektor, dessen Richtungslinie unter der Wirkung des Operators erhalten bleibt. Der Operator verändert ihn lediglich durch Multiplikation mit einem Skalar, dem zugehörigen Eigenwert \\[10, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (60,1,25,NULL,10,'[10, 82, 13]',686,'Eigenwerte und Eigenvektoren bilden einen zentralen Bestandteil der linearen Algebra, weil sie wesentliche Eigenschaften eines Operators unmittelbar beschreiben und zahlreiche Berechnungen vereinfachen. Sie spielen unter anderem bei Stabilitätsuntersuchungen, Spektralzerlegungen und Differentialgleichungen eine grundlegende Rolle \\[10, 82, 13\\]. Der Originalabschnitt endet mit genau dieser Einführung des Eigenwertproblems.','unresolved');
