INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (63,1,25,NULL,10,'[10, 71, 82, 13]',690,'Mit den in diesem Abschnitt eingeführten Begriffen erweitere ich den mathematischen Apparat gegenüber dem allgemeinen Funktionsbegriff wesentlich. Funktionen beschreiben eindeutige Zuordnungen zwischen Mengen. Lineare Abbildungen erhalten zusätzlich algebraische Strukturen. Operatoren wirken innerhalb eines gemeinsamen Vektorraums, und Matrizen stellen diese Operatoren bezüglich einer gewählten Basis dar. Eigenwerte und Eigenvektoren charakterisieren schließlich besondere Wirkungsrichtungen eines Operators \\[10, 71, 82, 13\\].','unresolved');
