INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (67,1,26,71,71,'[71, 74, 82]',722,'Nachdem ich im vorhergehenden Abschnitt lineare Abbildungen und Operatoren eingeführt habe, muss ich nun den mathematischen Raum genauer bestimmen, auf dessen Elementen solche Operatoren wirken. Die lineare Algebra beschreibt einen solchen Raum durch den Begriff des Vektorraums. Dabei wird eine Menge von Elementen mit einer inneren Addition und einer äußeren Skalarmultiplikation verbunden \\[71, 74, 82\\]. Der ursprüngliche Abschnitt entwickelt hierzu die Vektorraumdefinition, die Vektorraumaxiome, Nullvektor und additives Inverses, die Eigenschaften der Skalarmultiplikation, Untervektorräume sowie elementare Beispiele.','resolved');
