INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (113,1,26,71,71,'[71, 74, 82]',896,'Aus diesen Bedingungen folgt insbesondere, dass jeder Untervektorraum den Nullvektor des übergeordneten Vektorraums enthält \\[71, 74, 82\\]. Im Original wurden Teilmengenbedingung, Additionsabschluss und Abschluss unter Skalarmultiplikation auf drei einzelne Gleichungsnummern verteilt; mathematisch bilden sie hier eine gemeinsame Untervektorraumbedingung.','resolved');
