INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (127,1,26,71,71,'[71, 82]',930,'Der Vektorraum stellt für mich eine abstrakte algebraische Struktur dar, durch die sehr unterschiedliche mathematische Objekte einheitlich behandelt werden können. Entscheidend ist nicht die konkrete Gestalt seiner Elemente, sondern die Erfüllung der Vektorraumaxiome \\[71, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (128,1,26,82,82,'[71, 82]',930,'Der Vektorraum stellt für mich eine abstrakte algebraische Struktur dar, durch die sehr unterschiedliche mathematische Objekte einheitlich behandelt werden können. Entscheidend ist nicht die konkrete Gestalt seiner Elemente, sondern die Erfüllung der Vektorraumaxiome \\[71, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (129,1,26,71,71,'[71, 74, 82]',932,'Durch die Einführung des Vektorraums kann ich anschließend lineare Kombinationen, Spannräume, lineare Unabhängigkeit, Basen und Dimensionen präzise definieren. Diese Begriffe benötige ich wiederum, um Zustände durch Koordinaten darzustellen und lineare Operatoren durch Matrizen zu beschreiben \\[71, 74, 82\\].','resolved');
