INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (132,1,26,71,71,'[71, 74, 82]',940,'Methodologisch ist für mich besonders wichtig, dass der Begriff des Vektorraums keine konkrete physikalische Interpretation seiner Elemente voraussetzt. Dieselben Vektorraumaxiome können für Koordinatenvektoren, Matrizen, Funktionen oder andere mathematische Objekte gelten \\[71, 74, 82\\].','resolved');
