INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (134,1,26,82,82,'[71, 74, 82]',940,'Methodologisch ist für mich besonders wichtig, dass der Begriff des Vektorraums keine konkrete physikalische Interpretation seiner Elemente voraussetzt. Dieselben Vektorraumaxiome können für Koordinatenvektoren, Matrizen, Funktionen oder andere mathematische Objekte gelten \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (135,1,27,71,71,'[71, 74, 82]',972,'Mit der Definition des Vektorraums habe ich die beiden grundlegenden Operationen der linearen Algebra eingeführt. Daraus ergibt sich unmittelbar die Frage, welche Vektoren ich aus bereits bekannten Vektoren konstruieren kann. Die lineare Algebra beantwortet diese Frage mit dem Begriff der Linearkombination. Er beschreibt, wie durch Skalarmultiplikation und anschließende Addition aus vorhandenen Vektoren weitere Vektoren entstehen \\[71, 74, 82\\]. Genau auf diesem Aufbau basiert auch der ursprüngliche Abschnitt 3.2.5.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (136,1,27,74,74,'[71, 74, 82]',972,'Mit der Definition des Vektorraums habe ich die beiden grundlegenden Operationen der linearen Algebra eingeführt. Daraus ergibt sich unmittelbar die Frage, welche Vektoren ich aus bereits bekannten Vektoren konstruieren kann. Die lineare Algebra beantwortet diese Frage mit dem Begriff der Linearkombination. Er beschreibt, wie durch Skalarmultiplikation und anschließende Addition aus vorhandenen Vektoren weitere Vektoren entstehen \\[71, 74, 82\\]. Genau auf diesem Aufbau basiert auch der ursprüngliche Abschnitt 3.2.5.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (137,1,27,82,82,'[71, 74, 82]',972,'Mit der Definition des Vektorraums habe ich die beiden grundlegenden Operationen der linearen Algebra eingeführt. Daraus ergibt sich unmittelbar die Frage, welche Vektoren ich aus bereits bekannten Vektoren konstruieren kann. Die lineare Algebra beantwortet diese Frage mit dem Begriff der Linearkombination. Er beschreibt, wie durch Skalarmultiplikation und anschließende Addition aus vorhandenen Vektoren weitere Vektoren entstehen \\[71, 74, 82\\]. Genau auf diesem Aufbau basiert auch der ursprüngliche Abschnitt 3.2.5.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (138,1,27,71,71,'[71, 74, 82]',974,'Die Linearkombination besitzt eine zentrale Bedeutung, weil nahezu alle unmittelbar folgenden Begriffe der linearen Algebra auf ihr aufbauen. Dazu gehören insbesondere Spannräume, Erzeugendensysteme, lineare Unabhängigkeit, Basen und Dimensionen. Ohne den Begriff der Linearkombination kann ich weder bestimmen, welche Vektoren sich aus einer gegebenen Vektormenge erzeugen lassen, noch welche Vektoren für die vollständige Beschreibung eines Vektorraums tatsächlich erforderlich sind \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (139,1,27,74,74,'[71, 74, 82]',974,'Die Linearkombination besitzt eine zentrale Bedeutung, weil nahezu alle unmittelbar folgenden Begriffe der linearen Algebra auf ihr aufbauen. Dazu gehören insbesondere Spannräume, Erzeugendensysteme, lineare Unabhängigkeit, Basen und Dimensionen. Ohne den Begriff der Linearkombination kann ich weder bestimmen, welche Vektoren sich aus einer gegebenen Vektormenge erzeugen lassen, noch welche Vektoren für die vollständige Beschreibung eines Vektorraums tatsächlich erforderlich sind \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (140,1,27,82,82,'[71, 74, 82]',974,'Die Linearkombination besitzt eine zentrale Bedeutung, weil nahezu alle unmittelbar folgenden Begriffe der linearen Algebra auf ihr aufbauen. Dazu gehören insbesondere Spannräume, Erzeugendensysteme, lineare Unabhängigkeit, Basen und Dimensionen. Ohne den Begriff der Linearkombination kann ich weder bestimmen, welche Vektoren sich aus einer gegebenen Vektormenge erzeugen lassen, noch welche Vektoren für die vollständige Beschreibung eines Vektorraums tatsächlich erforderlich sind \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (141,1,27,71,71,'[71, 82]',998,'Jede solche Linearkombination ist aufgrund der Vektorraumaxiome wiederum ein Element desselben Vektorraums \\[71, 82\\]. Die ältere Repository-Fassung beschreibt die Linearkombination entsprechend als Summe $\\lambda_{1}v_{1} + \\cdots + \\lambda_{n}v_{n}$.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (142,1,27,82,82,'[71, 82]',998,'Jede solche Linearkombination ist aufgrund der Vektorraumaxiome wiederum ein Element desselben Vektorraums \\[71, 82\\]. Die ältere Repository-Fassung beschreibt die Linearkombination entsprechend als Summe $\\lambda_{1}v_{1} + \\cdots + \\lambda_{n}v_{n}$.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (143,1,27,71,71,'[71, 74]',1000,'Die Skalare bestimmen den jeweiligen Beitrag der einzelnen Vektoren zur resultierenden Linearkombination. Verändere ich einen oder mehrere dieser Skalare, erhalte ich im Allgemeinen einen anderen Vektor \\[71, 74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (144,1,27,74,74,'[71, 74]',1000,'Die Skalare bestimmen den jeweiligen Beitrag der einzelnen Vektoren zur resultierenden Linearkombination. Verändere ich einen oder mehrere dieser Skalare, erhalte ich im Allgemeinen einen anderen Vektor \\[71, 74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (145,1,27,74,74,'[74, 82]',1028,'Dieses Beispiel zeigt, wie aus gegebenen Vektoren durch geeignete Wahl der Skalare ein weiterer Vektor desselben Vektorraums entsteht. Der resultierende Vektor muss im Allgemeinen mit keinem der Ausgangsvektoren übereinstimmen \\[74, 82\\]. Der Originalabschnitt enthält genau diesen didaktischen Schritt von zwei gegebenen Vektoren zu einer konkreten Linearkombination.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (146,1,27,82,82,'[74, 82]',1028,'Dieses Beispiel zeigt, wie aus gegebenen Vektoren durch geeignete Wahl der Skalare ein weiterer Vektor desselben Vektorraums entsteht. Der resultierende Vektor muss im Allgemeinen mit keinem der Ausgangsvektoren übereinstimmen \\[74, 82\\]. Der Originalabschnitt enthält genau diesen didaktischen Schritt von zwei gegebenen Vektoren zu einer konkreten Linearkombination.','resolved');
