INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (149,1,27,71,71,'[71, 82]',1046,'Der Spannraum ist nicht lediglich eine beliebige Teilmenge des Vektorraums. Er ist selbst ein Untervektorraum von $V$ und zugleich der kleinste Untervektorraum, der alle betrachteten Vektoren $v_{1},\\ldots,v_{n}$ enthält \\[71, 82\\].','resolved');
