INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (156,1,27,71,71,'[71, 74]',1062,'Das bedeutet nicht, dass die Darstellung eines Vektors durch ein Erzeugendensystem eindeutig sein muss. Enthält das Erzeugendensystem mehr Vektoren als für die Erzeugung des Raums erforderlich sind, kann derselbe Vektor durch unterschiedliche Linearkombinationen dargestellt werden \\[71, 74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (157,1,27,74,74,'[71, 74]',1062,'Das bedeutet nicht, dass die Darstellung eines Vektors durch ein Erzeugendensystem eindeutig sein muss. Enthält das Erzeugendensystem mehr Vektoren als für die Erzeugung des Raums erforderlich sind, kann derselbe Vektor durch unterschiedliche Linearkombinationen dargestellt werden \\[71, 74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (158,1,27,71,71,'[71, 74, 82]',1068,'Enthält ein Erzeugendensystem einen Vektor, der bereits als Linearkombination der übrigen Vektoren dargestellt werden kann, trägt dieser Vektor nichts zusätzlich zum Spannraum bei. Ich kann ihn entfernen, ohne den erzeugten Raum zu verändern \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (159,1,27,74,74,'[71, 74, 82]',1068,'Enthält ein Erzeugendensystem einen Vektor, der bereits als Linearkombination der übrigen Vektoren dargestellt werden kann, trägt dieser Vektor nichts zusätzlich zum Spannraum bei. Ich kann ihn entfernen, ohne den erzeugten Raum zu verändern \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (160,1,27,82,82,'[71, 74, 82]',1068,'Enthält ein Erzeugendensystem einen Vektor, der bereits als Linearkombination der übrigen Vektoren dargestellt werden kann, trägt dieser Vektor nichts zusätzlich zum Spannraum bei. Ich kann ihn entfernen, ohne den erzeugten Raum zu verändern \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (161,1,27,71,71,'[71, 74, 82]',1078,'Die Linearkombination bildet eine der grundlegenden Konstruktionen innerhalb eines Vektorraums. Aus ihr entstehen Spannräume, Erzeugendensysteme, Basen und schließlich Koordinatendarstellungen. Damit bildet sie den Ausgangspunkt für einen großen Teil der strukturellen Untersuchungen der linearen Algebra \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (162,1,27,74,74,'[71, 74, 82]',1078,'Die Linearkombination bildet eine der grundlegenden Konstruktionen innerhalb eines Vektorraums. Aus ihr entstehen Spannräume, Erzeugendensysteme, Basen und schließlich Koordinatendarstellungen. Damit bildet sie den Ausgangspunkt für einen großen Teil der strukturellen Untersuchungen der linearen Algebra \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (163,1,27,82,82,'[71, 74, 82]',1078,'Die Linearkombination bildet eine der grundlegenden Konstruktionen innerhalb eines Vektorraums. Aus ihr entstehen Spannräume, Erzeugendensysteme, Basen und schließlich Koordinatendarstellungen. Damit bildet sie den Ausgangspunkt für einen großen Teil der strukturellen Untersuchungen der linearen Algebra \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (164,1,28,71,71,'[71, 74, 82]',1161,'Mit dem Spannraum kann ich bestimmen, welche Vektoren sich aus einer gegebenen Vektormenge durch Linearkombinationen erzeugen lassen. Damit ist jedoch noch nicht geklärt, ob alle verwendeten Vektoren tatsächlich erforderlich sind. Enthält eine Vektormenge einen Vektor, der bereits durch die übrigen Vektoren erzeugt werden kann, ist dieser für die Erzeugung des Spannraums redundant. Die lineare Algebra erfasst diesen Unterschied durch die Begriffe der linearen Unabhängigkeit und linearen Abhängigkeit \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (165,1,28,74,74,'[71, 74, 82]',1161,'Mit dem Spannraum kann ich bestimmen, welche Vektoren sich aus einer gegebenen Vektormenge durch Linearkombinationen erzeugen lassen. Damit ist jedoch noch nicht geklärt, ob alle verwendeten Vektoren tatsächlich erforderlich sind. Enthält eine Vektormenge einen Vektor, der bereits durch die übrigen Vektoren erzeugt werden kann, ist dieser für die Erzeugung des Spannraums redundant. Die lineare Algebra erfasst diesen Unterschied durch die Begriffe der linearen Unabhängigkeit und linearen Abhängigkeit \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (166,1,28,82,82,'[71, 74, 82]',1161,'Mit dem Spannraum kann ich bestimmen, welche Vektoren sich aus einer gegebenen Vektormenge durch Linearkombinationen erzeugen lassen. Damit ist jedoch noch nicht geklärt, ob alle verwendeten Vektoren tatsächlich erforderlich sind. Enthält eine Vektormenge einen Vektor, der bereits durch die übrigen Vektoren erzeugt werden kann, ist dieser für die Erzeugung des Spannraums redundant. Die lineare Algebra erfasst diesen Unterschied durch die Begriffe der linearen Unabhängigkeit und linearen Abhängigkeit \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (167,1,28,71,71,'[71, 74, 82]',1163,'Diese Unterscheidung führt unmittelbar zum Basisbegriff. Eine Basis soll einerseits den gesamten Vektorraum erzeugen, andererseits aber keine überflüssigen Vektoren enthalten. Sie ist deshalb ein linear unabhängiges Erzeugendensystem. Die Anzahl der Vektoren einer Basis bestimmt bei endlichdimensionalen Vektorräumen schließlich deren Dimension \\[71, 74, 82\\].','resolved');
