INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (198,1,29,71,71,'[71, 74, 82]',1439,'Mit einer Basis kann ich jeden Vektor eines endlichdimensionalen Vektorraums eindeutig durch Koordinaten beschreiben. Diese Koordinaten gehören jedoch nicht zum Vektor selbst. Sie entstehen erst dadurch, dass ich eine bestimmte Basis für seine Darstellung auswähle. Wähle ich eine andere Basis desselben Vektorraums, können sich sämtliche Koordinaten ändern, obwohl der mathematische Vektor unverändert bleibt \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (199,1,29,74,74,'[71, 74, 82]',1439,'Mit einer Basis kann ich jeden Vektor eines endlichdimensionalen Vektorraums eindeutig durch Koordinaten beschreiben. Diese Koordinaten gehören jedoch nicht zum Vektor selbst. Sie entstehen erst dadurch, dass ich eine bestimmte Basis für seine Darstellung auswähle. Wähle ich eine andere Basis desselben Vektorraums, können sich sämtliche Koordinaten ändern, obwohl der mathematische Vektor unverändert bleibt \\[71, 74, 82\\].','resolved');
