INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (230,1,30,71,71,'[71, 74, 82]',1713,'Nachdem ich lineare Operatoren durch Matrizen beschrieben und die Abhängigkeit ihrer Matrixdarstellung von der gewählten Basis untersucht habe, benötige ich nun eine Größe, mit der ich die geometrische Wirkung einer linearen Transformation quantitativ erfassen kann. Für quadratische Matrizen übernimmt die Determinante diese Funktion. Sie beschreibt gleichzeitig, ob eine lineare Transformation Flächen beziehungsweise Volumina vergrößert oder verkleinert, ob sie die Orientierung erhält oder umkehrt und ob durch die Transformation eine Dimension verloren geht \\[71, 74, 82\\].','resolved');
