INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (241,1,30,74,74,'[74, 82]',1763,'Die durch diese Matrix dargestellte lineare Transformation vergrößert Flächeninhalte damit um den Faktor $6$ \\[74, 82\\]. Das entspricht unmittelbar der anschaulichen Wirkung der Matrix: Eine Richtung wird mit dem Faktor $2$, die andere mit dem Faktor $3$ skaliert. Der resultierende Flächenfaktor ist das Produkt beider Skalierungen.','resolved');
