INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (268,1,31,71,71,'[71, 74, 82]',2045,'Die Determinante liefert mir für quadratische Matrizen ein Kriterium dafür, ob eine lineare Transformation invertierbar ist. Lineare Abbildungen müssen jedoch weder durch quadratische Matrizen dargestellt werden noch zwischen Vektorräumen gleicher Dimension wirken. Für diese allgemeinere Situation benötige ich Begriffe, die unabhängig von der Quadratform einer Matrix beschreiben, welche Richtungen durch eine Abbildung erreicht werden, welche vollständig verschwinden und wie viele unabhängige Richtungen tatsächlich übertragen werden. Genau diese Aufgaben übernehmen Bild, Kern und Rang \\[71, 74, 82\\].','resolved');
