INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (303,1,32,71,71,'[71, 74, 82]',2367,'Genau diese Richtungen werden durch Eigenvektoren beschrieben. Der zugehörige Skalierungsfaktor ist der Eigenwert. Beide Begriffe gehören zu den zentralen Werkzeugen der linearen Algebra, weil sie komplexe lineare Transformationen auf besonders einfache Wirkungen entlang bestimmter Richtungen zurückführen \\[71, 74, 82\\].','resolved');
