INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (312,1,32,71,71,'[71, 74, 82]',2487,'Der Eigenraum enthält damit den Nullvektor und sämtliche Eigenvektoren, die zum Eigenwert $\\lambda$ gehören \\[71, 74, 82\\].','resolved');
