INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (319,1,32,74,74,'[71, 74, 82]',2571,'Die Determinante ist damit das Produkt aller Eigenwerte \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (320,1,32,82,82,'[71, 74, 82]',2571,'Die Determinante ist damit das Produkt aller Eigenwerte \\[71, 74, 82\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (321,1,33,74,74,'[74]',2734,'Mit Eigenwerten und Eigenvektoren kann ich diejenigen Richtungen eines linearen Operators bestimmen, die unter seiner Wirkung lediglich skaliert werden. Der nächste Schritt besteht darin zu prüfen, ob sich aus diesen ausgezeichneten Richtungen eine vollständige Basis des betrachteten Vektorraums bilden lässt. Ist das möglich, kann ich die Matrixdarstellung des Operators durch einen geeigneten Basiswechsel auf eine Diagonalmatrix zurückführen. Genau darin liegt die Idee der Diagonalisierung \\[74\\]. Strang behandelt diesen Zusammenhang ausdrücklich in Kapitel 6, insbesondere in §6.2 „Diagonalizing a Matrix".','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (322,1,33,74,74,'[74]',2736,'Die Bedeutung dieser Umformung liegt für mich nicht darin, dass ein anderer Operator entsteht. Wie beim allgemeinen Basiswechsel bleibt der lineare Operator selbst unverändert. Lediglich seine Matrixdarstellung wird in einer besonders geeigneten Basis wesentlich einfacher. Wenn diese Basis aus Eigenvektoren besteht, wirkt der Operator entlang jeder Basisrichtung nur noch durch Multiplikation mit dem zugehörigen Eigenwert \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (323,1,33,74,74,'[74]',2759,'Die Spalten von $P$ werden dabei aus linear unabhängigen Eigenvektoren von $A$ gebildet. Die zugehörigen Eigenwerte stehen in derselben Reihenfolge auf der Hauptdiagonale von $D$ \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (324,1,33,74,74,'[74]',2807,'Eine $n \\times n$-Matrix ist genau dann diagonalisierbar, wenn sie $n$ linear unabhängige Eigenvektoren besitzt \\[74\\]. Das offizielle MIT-Material formuliert die Diagonalisierung entsprechend über eine Matrix aus unabhängigen Eigenvektoren.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (325,1,33,74,74,'[74]',2815,'Besitzt eine $n \\times n$-Matrix $n$ paarweise verschiedene Eigenwerte, so besitzt sie automatisch $n$ linear unabhängige Eigenvektoren und ist damit diagonalisierbar \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (326,1,33,74,74,'[74]',2986,'Damit reduziert sich die wiederholte Anwendung eines linearen Operators auf die Potenzierung seiner Eigenwerte. Dieser Zusammenhang ist ein zentraler Grund dafür, warum Diagonalisierung bei iterierten linearen Prozessen so nützlich ist \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (327,1,33,74,74,'[74]',3009,'Eine besonders starke Form der Diagonalisierung tritt bei reellen symmetrischen Matrizen auf. Strang behandelt symmetrische Matrizen unmittelbar in §6.4 und verweist dort ausdrücklich auf den Spektralsatz. Die offiziellen Lösungen bestätigen, dass die Eigenvektoren symmetrischer Matrizen orthogonal gewählt werden können. \\[74\\]','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (328,1,33,74,74,'[74]',3026,'Diese Aussage ist die endlichdimensionale Form des **Spektralsatzes für reelle symmetrische Matrizen** \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (329,1,33,74,74,'[74]',3047,'Damit besitzt jede reelle symmetrische Matrix eine orthonormale Eigenvektorbasis und ausschließlich reelle Eigenwerte \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (330,1,33,74,74,'[74]',3124,'Existiert eine vollständige Eigenvektorbasis, kann ich den Operator in dieser Basis diagonal darstellen. Dann wirkt er auf jede Eigenrichtung unabhängig durch Multiplikation mit einem einzigen Eigenwert \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (331,1,33,74,74,'[74]',3126,'Für symmetrische Matrizen ist die Situation noch stärker strukturiert. Ihre Eigenvektoren können orthonormal gewählt werden und ihre Eigenwerte sind reell. Dadurch entsteht eine orthogonale Spektralzerlegung des gesamten Raums \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (332,1,33,74,74,'[74]',3198,'Für reelle symmetrische Matrizen liefert der Spektralsatz eine noch stärkere Struktur: Es existiert eine orthonormale Eigenbasis, sodass der Operator orthogonal diagonalisiert und als Summe seiner Eigenprojektoren dargestellt werden kann \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (333,1,34,74,74,'[74]',3212,'Als zentrale Literaturgrundlage verwende ich hierfür **Gilbert Strang: *Introduction to Linear Algebra*. 5th Edition. Wellesley, Massachusetts: Wellesley-Cambridge Press, 2016 \\[74\\]**. Strang behandelt Längen und Skalarprodukte bereits in §1.2 und führt die darauf aufbauenden Begriffe der Orthogonalität, Projektion und orthonormalen Basen systematisch in Kapitel 4 weiter.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (334,1,34,84,84,'[84]',3214,'Ergänzend ziehe ich **Stephen H. Friedberg, Arnold J. Insel und Lawrence E. Spence: *Linear Algebra*. 5th Edition. Pearson, 2018 \\[84\\]** heran. Dort bilden Skalarprodukte und Normen den Ausgangspunkt von Kapitel 6 „Inner Product Spaces"; anschließend folgen Gram-Schmidt, orthogonale Komplemente, orthogonale Projektionen und der Spektralsatz.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (335,1,34,84,84,'[84]',3244,'Diese Eigenschaften bilden gemeinsam die mathematische Grundlage dafür, aus dem Skalarprodukt geometrische Größen abzuleiten \\[84\\]. Kapitel 6.1 von Friedberg, Insel und Spence ist ausdrücklich den „Inner Products and Norms" gewidmet.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (336,1,34,74,74,'[74]',3277,'Strang behandelt genau diesen Zusammenhang zwischen Vektorlänge und Skalarprodukt bereits in §1.2 „Lengths and Dot Products" \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (337,1,34,84,84,'[84]',3297,'Damit verallgemeinere ich unmittelbar den Satz des Pythagoras auf den (n)-dimensionalen euklidischen Raum. Diese Definition der Norm aus dem Skalarprodukt ist Standardbestandteil der Theorie der Skalarprodukträume \\[84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (338,1,34,74,74,'[74]',3384,'Strang entwickelt Orthogonalität, Projektionen und orthogonale Basen zusammenhängend in Kapitel 4 \\[74\\]. Friedberg, Insel und Spence behandeln dieselbe Struktur in Kapitel 6 über Skalarprodukträume und orthogonale Komplemente \\[84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (339,1,34,84,84,'[84]',3384,'Strang entwickelt Orthogonalität, Projektionen und orthogonale Basen zusammenhängend in Kapitel 4 \\[74\\]. Friedberg, Insel und Spence behandeln dieselbe Struktur in Kapitel 6 über Skalarprodukträume und orthogonale Komplemente \\[84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (340,1,34,84,84,'[84]',3500,'Die Zerlegung in einen Anteil innerhalb eines Unterraums und einen dazu orthogonalen Anteil bildet die Grundlage der orthogonalen Projektion. Friedberg, Insel und Spence führen orthogonale Komplemente und den Gram-Schmidt-Prozess gemeinsam in §6.2 sowie orthogonale Projektionen in §6.6 \\[84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (341,1,34,74,74,'[74]',3522,'Strang behandelt Projektionen ausdrücklich in §4.2 \\[74\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (342,1,34,74,74,'[74, 84]',3572,'Eine beliebige linear unabhängige Basis ist im Allgemeinen nicht orthogonal. Ich kann sie jedoch systematisch in eine orthonormale Basis desselben Unterraums überführen. Dieses Verfahren ist die Gram-Schmidt-Orthogonalisierung \\[74, 84\\]. Strang behandelt sie ausdrücklich in §4.4, Friedberg, Insel und Spence in §6.2.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (343,1,34,84,84,'[74, 84]',3572,'Eine beliebige linear unabhängige Basis ist im Allgemeinen nicht orthogonal. Ich kann sie jedoch systematisch in eine orthonormale Basis desselben Unterraums überführen. Dieses Verfahren ist die Gram-Schmidt-Orthogonalisierung \\[74, 84\\]. Strang behandelt sie ausdrücklich in §4.4, Friedberg, Insel und Spence in §6.2.','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (344,1,34,74,74,'[74, 84]',3739,'Die Gram-Schmidt-Orthogonalisierung zeigt schließlich, dass ich eine ungünstige, schiefwinklige Basis nicht einfach hinnehmen muss. Solange die Ausgangsvektoren linear unabhängig sind, kann ich aus ihnen schrittweise eine orthonormale Basis desselben Unterraums konstruieren \\[74, 84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (345,1,34,84,84,'[74, 84]',3739,'Die Gram-Schmidt-Orthogonalisierung zeigt schließlich, dass ich eine ungünstige, schiefwinklige Basis nicht einfach hinnehmen muss. Solange die Ausgangsvektoren linear unabhängig sind, kann ich aus ihnen schrittweise eine orthonormale Basis desselben Unterraums konstruieren \\[74, 84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (346,1,34,74,74,'[74, 84]',3745,'Mit dem Skalarprodukt habe ich den bisher rein algebraisch behandelten Vektorräumen eine zusätzliche geometrische Struktur gegeben. Aus dem Skalarprodukt konnte ich Norm, Abstand und Winkel ableiten. Orthogonalität lässt sich durch das Verschwinden des Skalarprodukts charakterisieren, und orthonormale Basen ermöglichen eine besonders einfache Zerlegung von Vektoren \\[74, 84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (347,1,34,84,84,'[74, 84]',3745,'Mit dem Skalarprodukt habe ich den bisher rein algebraisch behandelten Vektorräumen eine zusätzliche geometrische Struktur gegeben. Aus dem Skalarprodukt konnte ich Norm, Abstand und Winkel ableiten. Orthogonalität lässt sich durch das Verschwinden des Skalarprodukts charakterisieren, und orthonormale Basen ermöglichen eine besonders einfache Zerlegung von Vektoren \\[74, 84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (348,1,34,74,74,'[74, 84]',3747,'Mit orthogonalen Projektionen kann ich einen Vektor eindeutig in einen Anteil innerhalb eines Unterraums und einen dazu orthogonalen Anteil zerlegen. Die Gram-Schmidt-Orthogonalisierung erlaubt mir wiederum, aus jeder linear unabhängigen endlichen Vektormenge eine orthonormale Basis ihres aufgespannten Unterraums zu erzeugen \\[74, 84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (349,1,34,84,84,'[74, 84]',3747,'Mit orthogonalen Projektionen kann ich einen Vektor eindeutig in einen Anteil innerhalb eines Unterraums und einen dazu orthogonalen Anteil zerlegen. Die Gram-Schmidt-Orthogonalisierung erlaubt mir wiederum, aus jeder linear unabhängigen endlichen Vektormenge eine orthonormale Basis ihres aufgespannten Unterraums zu erzeugen \\[74, 84\\].','resolved');
INSERT INTO `citation_occurrences` (`citation_occurrence_id`,`document_id`,`section_id`,`source_id`,`source_citation_number`,`citation_group_text`,`source_line_no`,`context_text`,`validation_status`) VALUES (350,1,34,74,74,'[74]',3757,'Für das folgende Repository-Skript sind damit **\\[74\\]** und die neue Literaturstelle **\\[84\\]** zu erfassen. Für \\[74\\] sind insbesondere §1.2, §4.2 und §4.4 als verifizierte source_usage-Bereiche verfügbar; für \\[84\\] sind §6.1, §6.2 und §6.6 durch das reale Inhaltsverzeichnis verifiziert. Wo der konkrete Quellentext nicht zugänglich verifiziert wurde, darf im SQL **kein erfundener source_excerpt** eingetragen werden.','resolved');
