INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (1,83,6,6,'location_paraphrase','direct','[6] stützt die Einordnung der Mengenlehre als grundlegenden mathematischen Werkzeugbestand und die Abfolge von Mengenoperationen über Relationen zu Funktionen.','The Axiom of Extension, S. 1–3; Unions and Intersections, S. 12–16; Ordered Pairs, S. 22–25; Relations, S. 26–29; Functions, S. 30–33.','Relations; Functions; Inverses and Composites','Die Springer-Gliederung zeigt, dass Halmos genau die in 3.2.0 angekündigten mengentheoretischen Grundobjekte und Abbildungsbegriffe systematisch aufbaut.',NULL,'https://link.springer.com/book/10.1007/978-1-4757-1645-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (2,84,71,71,'location_paraphrase','direct','[71] stützt die Einordnung von Gruppen, Ringen, Moduln sowie Matrizen und linearen Abbildungen als algebraische Grundstrukturen.','Groups, S. 3–82; Rings, S. 83–116; Modules, S. 117–172; Matrices and Linear Maps, S. 503–552.','Groups; Rings; Modules; Matrices and Linear Maps','Langs Inhaltsstruktur deckt die im Absatz genannten algebraischen Strukturen und die spätere lineare Abbildungstheorie unmittelbar ab.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (3,85,72,72,'location_paraphrase','direct','[72] stützt die Einordnung von Konvergenz, Stetigkeit, Differentiation und Integration in der Analysis.','Kap. 3 Numerical Sequences and Series; Kap. 4 Continuity; Kap. 5 Differentiation; Kap. 6 The Riemann-Stieltjes Integral; Kap. 7 Sequences and Series of Functions.','Continuity; Differentiation; The Riemann-Stieltjes Integral','Die offizielle McGraw-Hill-Gliederung weist die im Dissertationstext genannten Kernbereiche der Analysis als eigene Kapitel aus.',NULL,'https://www.mheducation.me/principles-of-mathematical-analysis-int-l-ed-9780070856134-mea',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (4,86,73,73,'location_paraphrase','direct','[73] stützt topologische Räume, Stetigkeit, Zusammenhang, Kompaktheit und Trennungsaxiome; die Topologie wird vor metrischen Spezialstrukturen entwickelt.','2. Aufl.: §§12–17 Topologies/Closed Sets; §§18–19 Continuous Functions; §§20–21 Metric Topologies; §§23–29 Connectedness/Compactness; §§30–32 Countability/Separation Axioms.','Topological Spaces and Continuous Functions; Connectedness and Compactness','Pearson und die von Munkres selbst gelehrte MIT-Leseliste bestätigen die Reihenfolge und die genannten Themen.',NULL,'https://ocw.mit.edu/courses/18-901-introduction-to-topology-fall-2004/pages/readings/','https://www.pearson.com/en-us/subject-catalog/p/Munkres-Topology-Classic-Version-2nd-Edition/P200000006299','university','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (5,87,74,74,'location_paraphrase','direct','[74] stützt Vektorräume, Matrizen, Basis/Dimension, Determinanten, Eigenwerte und lineare Transformationen.','Kap. 3, S. 123 ff.; Kap. 5, S. 247 ff.; Kap. 6, S. 288 ff.; Kap. 8, S. 401 ff.','Vector Spaces and Subspaces; Determinants; Eigenvalues and Eigenvectors; Linear Transformations','Das offizielle Inhaltsverzeichnis der 5. Auflage deckt genau die in 3.2.0 als lineare Algebra angekündigten Werkzeuge ab.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (6,88,75,75,'location_paraphrase','direct','[75] stützt normierte Räume, Banach- und Hilberträume, lineare Operatoren/Funktionale und Spektraltheorie.','Normed Spaces/Banach Spaces ab S. 49; Linear Operators ab S. 82; Linear Functionals ab S. 103; Inner Product/Hilbert Spaces ab S. 127; Spectral Theory of Bounded Self-Adjoint Linear Operators ab S. 459.','Normed Spaces; Banach Spaces; Inner Product Spaces; Hilbert Spaces; Spectral Theory','Die Inhaltsübersichten der Ausgabe 1978 und der Wiley-Neuauflage stimmen in diesen Kernbereichen überein.',NULL,'https://books.google.com/books?id=Va8rAAAAYAAJ','https://www.wiley-vch.de/de/fachgebiete/mathematik-und-statistik/introductory-functional-analysis-with-applications-978-0-471-50459-7','book_preview','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (7,89,76,76,'location_paraphrase','direct','[76] stützt Hilberträume, normierte lineare Räume, Operatoren, Spektrum und Spektralsatz.','Kap. II Hilbert Spaces, S. 36 ff.; Kap. III Banach Spaces, S. 67 ff.; Kap. VI Bounded Operators, S. 182 ff.; Kap. VII The Spectral Theorem, S. 221 ff.','Hilbert Spaces; Bounded Operators; The Spectral Theorem','Reed/Simon behandeln die im Absatz genannten funktionalanalytischen Strukturen ausdrücklich in eigenen Kapiteln.',NULL,'https://books.google.com/books?id=bvuRuwuFBWwC','https://shop.elsevier.com/books/methods-of-modern-mathematical-physics/reed/978-0-12-585001-8','book_preview','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (8,90,77,77,'direct_quote','direct','[77] stützt die Grundidee diskreter Strukturen aus Knoten/Vertices und Kanten/Edges.','Kap. 1 The Basics, §1.1 Graphs, gedruckte S. 2 (PDF-Seite 21).','§1.1 Graphs','Diestel definiert einen Graphen als Paar aus Knotenmenge und Kantenmenge und erläutert anschließend Vertices und Edges.','A graph is a pair G = (V,E) of sets.','https://link.springer.com/book/10.1007/978-3-662-53622-3','https://daiwz.net/course/disc_math/2023/Diestel_Graph_Theory.pdf','publisher_plus_fulltext','verified','short_excerpt','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (9,91,78,78,'location_paraphrase','direct','[78] stützt die kategorientheoretische Beschreibung mathematischer Strukturen über Objekte, Morphismen/Funktoren und strukturerhaltende Beziehungen.','Kap. Categories, Functors, and Natural Transformations, S. 7–30; Constructions on Categories, S. 31–53.','Categories, Functors, and Natural Transformations','Die Kapitelstruktur belegt den Übergang von Einzelobjekten zu morphismen- und funktororientierter Strukturbetrachtung.',NULL,'https://link.springer.com/book/10.1007/978-1-4757-4721-8',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (10,92,79,79,'location_paraphrase','direct','[79] stützt die Unterscheidung formaler Symbole, Formationsregeln, Transformationsregeln, Postulate/Axiome und formale Theoreme.','Kap. IV A Formal System, S. 69–85; §§16–19, insbesondere §19 Transformation Rules, S. 81 ff.','A Formal System; Transformation Rules','Die recherchierte Gliederung und Textnachweise zeigen den Aufbau eines formalen Systems aus Syntax, Bildungsregeln, Postulaten und Schlussregeln.',NULL,'https://books.google.com/books/about/Introduction_to_Metamathematics.html?id=gFgPAQAAMAAJ',NULL,'book_preview','partial','location_only','2026-08-29','Die genaue 1952-Ausgabe ist bibliographisch zu klären; Fundstelle ist editionsabhängig vor Endfassung erneut abzugleichen.');
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (11,93,6,6,'location_paraphrase','direct','[6] stützt Mengen, Teilmengen/Mengenoperationen, Potenzmengen, geordnete Paare, Relationen und Funktionen.','Extension S. 1–3; Specification S. 4–7; Unordered Pairs S. 8–11; Unions/Intersections S. 12–16; Complements/Powers S. 17–21; Ordered Pairs S. 22–25; Relations S. 26–29.','Unions and Intersections; Complements and Powers; Ordered Pairs; Relations','Die Fundstellen entsprechen unmittelbar dem Aufbau von 3.2.1.',NULL,'https://link.springer.com/book/10.1007/978-1-4757-1645-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (12,94,67,67,'location_paraphrase','direct','[67] stützt die strukturorientierte Sicht, nach der mathematische Objekte wesentlich als Positionen in Mustern/Strukturen betrachtet werden.','Kap. 10 Mathematical Objects as Positions in Patterns, S. 201–223; §2 Patterns and their Relationships, S. 202–208; §3 Patterns and Positions: Entity and Identity, S. 209–212.','Mathematical Objects as Positions in Patterns','Resnik entwickelt die Identität mathematischer Objekte über ihre Position in Mustern und die Relationen innerhalb dieser Muster.',NULL,'https://books.google.com/books/about/Mathematics_as_a_Science_of_Patterns.html?id=SN_nCwAAQBAJ','https://academic.oup.com/book/32824/chapter-abstract/275104225','book_preview','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (13,95,68,68,'location_paraphrase','direct','[68] stützt strukturalistische Auffassungen mathematischer Objekte als Plätze innerhalb von Strukturen.','Kap. 3 Structure, S. 71–108.','Structure','Shapiros Kapitel behandelt den Status von Strukturen und ausdrücklich den Status mathematischer Objekte als Plätze innerhalb solcher Strukturen.',NULL,'https://academic.oup.com/book/32743/chapter-abstract/272846529',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (14,96,78,78,'location_paraphrase','partial','[78] stützt den strukturellen Fokus auf Objekte und Morphismen; die im Text zusätzlich verwendete allgemeine Relationssprache stammt nicht spezifisch aus der Kategorientheorie.','Categories, Functors, and Natural Transformations, S. 7–30.','Categories, Functors, and Natural Transformations','Mac Lane liefert belastbare Stützung für Objekte und strukturierte Abbildungen/Morphismen, aber nicht als Primärquelle für die allgemeine binäre Relationsdefinition.',NULL,'https://link.springer.com/book/10.1007/978-1-4757-4721-8',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (15,97,80,80,'location_paraphrase','direct','[80] stützt axiomatische Mengenoperationen, geordnete Paare, Relationen, Funktionen und kartesische Produkte.','Kap. 2 Axioms and Operations; Kap. 3 Relations and Functions: Ordered Pairs, Relations, n-Ary Relations, Functions, Infinite Cartesian Products.','Axioms and Operations; Relations and Functions','Endertons Kapitelstruktur entspricht unmittelbar den in 3.2.1 eingeführten mengentheoretischen Operationen und Relationsbegriffen.',NULL,'https://shop.elsevier.com/books/elements-of-set-theory/enderton/978-0-08-057042-6',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (16,98,81,81,'location_paraphrase','direct','[81] stützt die axiomatische Einordnung der Mengenlehre sowie Ordinal-/Kardinalzahlen und Auswahlprinzipien.','Basic Set Theory: Axioms of Set Theory S. 3–15; Ordinal Numbers S. 17–26; Cardinal Numbers S. 27–35; Axiom of Choice and Cardinal Arithmetic S. 47–61.','Axioms of Set Theory; Ordinal Numbers; Cardinal Numbers','Jechs offizielles Inhaltsverzeichnis belegt genau die im Text genannten weiterführenden Bereiche.',NULL,'https://link.springer.com/book/10.1007/3-540-44761-X',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (17,99,71,71,'location_paraphrase','supporting','[71] stützt Abbildungen/lineare Abbildungen im algebraischen Kontext; für die mengentheoretische Funktionsdefinition ist Enderton die direktere Quelle.','Matrices and Linear Maps, S. 503–552.','Matrices and Linear Maps','Lang zeigt die strukturelle Verwendung von Abbildungen und linearen Maps in der Algebra.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (18,100,72,72,'location_paraphrase','supporting','[72] stützt Funktionen als zentralen Gegenstand der Analysis sowie Grenzwerte, Stetigkeit und Differentiation.','Kap. 4 Continuity; Kap. 5 Differentiation; Kap. 9 Functions of Several Variables.','Continuity; Differentiation; Functions of Several Variables','Rudin entwickelt analytische Eigenschaften von Funktionen; die reine mengentheoretische Funktionsdefinition wird besser durch Enderton gestützt.',NULL,'https://www.mheducation.me/principles-of-mathematical-analysis-int-l-ed-9780070856134-mea',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (19,101,80,80,'location_paraphrase','direct','[80] stützt die Definition von Funktionen aus dem Relationsbegriff sowie geordnete Paare und kartesische Produkte.','Kap. 3 Relations and Functions, insbesondere Ordered Pairs, Relations, Functions.','Relations and Functions','Enderton ist für die in 3.2.2 verwendete mengentheoretische Funktionsdefinition die direkt passende Quelle.',NULL,'https://shop.elsevier.com/books/elements-of-set-theory/enderton/978-0-08-057042-6',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (20,102,82,82,'location_paraphrase','supporting','[82] stützt lineare Abbildungen und Operatoren als weiterführende Form von Abbildungen auf Vektorräumen.','Transformations, S. 55–117.','Transformations','Halmos behandelt Abbildungen in der speziell linearen, endlichdimensionalen Struktur; für allgemeine Funktionen ist die Quelle ergänzend.',NULL,'https://link.springer.com/book/10.1007/978-1-4612-6387-6',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (21,103,83,83,'location_paraphrase','direct','[83] stützt Mengen/Funktionen als analytische Grundlage und die Weiterführung zu Grenzwerten, Stetigkeit und Differentiation.','Kap. 1 Preliminaries, Abschnitt Sets and Functions; Kap. 4 Limits; Kap. 5 Continuous Functions; Kap. 6 Differentiation.','Preliminaries; Sets and Functions','Die 4. Auflage führt Funktionen explizit im Grundlagenkapitel und anschließend als Gegenstand der reellen Analysis.',NULL,'https://books.google.com/books/about/Introduction_to_Real_Analysis.html?id=YawbAAAAQBAJ','https://www.wiley-vch.de/en/areas-interest/mathematics-statistics/introduction-to-real-analysis-978-0-471-43331-6','book_preview','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (22,104,74,74,'replacement_location','replacement','Der bisherige Verweis [10] in 3.2.3 wird sachlich durch Strang [74] ersetzt: lineare Transformationen, Matrixdarstellung und Eigenwerte.','§8.1 The Idea of a Linear Transformation, S. 401; §8.2 The Matrix of a Linear Transformation, S. 411; §6.1 Introduction to Eigenvalues, S. 288.','Linear Transformations; Introduction to Eigenvalues','Die Fundstellen decken genau die mit [10] belegten Aussagen zur Matrixdarstellung linearer Operatoren und zur Eigenwertgleichung ab.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29','Kanonische Ersatzquelle gemäß früherem FRZK-Repository; Originalziffer [10] bleibt nur als Importhistorie erhalten.');
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (23,105,76,76,'replacement_location','replacement','Der bisherige Verweis [13] in 3.2.3 wird sachlich durch Reed/Simon [76] ersetzt: Operatoren, Adjunkte, Spektrum und inverse/operatorentheoretische Strukturen.','Kap. VI Bounded Operators, S. 182 ff.; §VI.2 Adjoints, S. 185; §VI.3 The Spectrum, S. 188; Kap. VII The Spectral Theorem, S. 221 ff.','Bounded Operators; The Spectrum; The Spectral Theorem','Reed/Simon liefern die operatorentheoretische Quelle für die Stellen, die im aktuellen DOCX vorläufig mit [13] belegt sind.',NULL,'https://books.google.com/books?id=bvuRuwuFBWwC','https://shop.elsevier.com/books/methods-of-modern-mathematical-physics/reed/978-0-12-585001-8','book_preview','cross_checked','location_only','2026-08-29','Kanonische Ersatzquelle gemäß früherem FRZK-Repository; Originalziffer [13] bleibt nur als Importhistorie erhalten.');
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (24,106,71,71,'location_paraphrase','direct','[71] stützt lineare Abbildungen, Matrixdarstellungen und die Darstellung eines Endomorphismus.','Matrices and Linear Maps, S. 503–552; Representation of One Endomorphism, S. 553–570.','Matrices and Linear Maps; Representation of One Endomorphism','Die beiden Kapitel decken die lineare Abbildung, Matrixdarstellung und Eigenstruktur des Abschnitts ab.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (25,107,80,80,'location_paraphrase','direct','[80] stützt die allgemeine Abbildung/Funktion als eindeutige Zuordnung auf Mengenebene.','Kap. 3 Relations and Functions: Ordered Pairs, Relations, Functions.','Relations and Functions','Diese Quelle stützt den allgemeinen Abbildungsbegriff, bevor 3.2.3 zur Linearität übergeht.',NULL,'https://shop.elsevier.com/books/elements-of-set-theory/enderton/978-0-08-057042-6',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (26,108,82,82,'location_paraphrase','direct','[82] stützt lineare Transformationen, Operatoren, Basiswechsel, Range/Nullspace sowie Determinanten- und Spektralterminologie.','Transformations, S. 55–117; Change of basis, S. 63; Range and null space, S. 69; Determinants and the spectral terminology, S. 77.','Transformations; Change of basis; Range and null space','Halmos behandelt die für 3.2.3 benötigte Operator- und Darstellungsstruktur direkt.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC','https://link.springer.com/book/10.1007/978-1-4612-6387-6','book_preview','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (27,109,71,71,'location_paraphrase','direct','[71] stützt Vektor-/Modulstrukturen und lineare Abbildungen; Vektorräume sind der Spezialfall von Moduln über einem Körper.','Modules, S. 117–172; Matrices and Linear Maps, S. 503–552.','Modules; Matrices and Linear Maps','Die Fundstellen tragen die algebraische Einordnung der Vektorraumaxiome und linearen Operationen.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (28,110,74,74,'location_paraphrase','direct','[74] stützt Vektorräume, Unterräume, Nullräume, Basis und Dimension.','Kap. 3 Vector Spaces and Subspaces, S. 123–193; §3.1 S. 123; §3.2 S. 135; §3.4 S. 164.','Vector Spaces and Subspaces','Die 5. Auflage behandelt die in 3.2.4 benötigte Vektorraumstruktur direkt.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (29,111,76,76,'location_paraphrase','supporting','[76] stützt die Einordnung endlichdimensionaler und normierter Vektorräume im funktionalanalytischen Rahmen.','Kap. I Preliminaries (metric and normed linear spaces); Kap. II Hilbert Spaces, S. 36 ff.; Kap. III Banach Spaces, S. 67 ff.','Hilbert Spaces; Banach Spaces','Reed/Simon sind hier eine ergänzende funktionalanalytische Quelle; die konkreten Vektorraumaxiome werden direkter durch Lang/Strang/Halmos gestützt.',NULL,'https://books.google.com/books?id=bvuRuwuFBWwC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (30,112,82,82,'location_paraphrase','direct','[82] stützt die Definition des Vektorraums, Basiskonstruktion und lineare Räume.','Spaces, S. 1–54; Definition of vector space, S. 1; Definition and construction of bases, S. 8.','Spaces; Definition of vector space','Halmos beginnt ausdrücklich mit der Vektorraumdefinition und entwickelt daraus die endlichdimensionale lineare Struktur.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC','https://link.springer.com/book/10.1007/978-1-4612-6387-6','book_preview','cross_checked','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (31,113,71,71,'location_paraphrase','direct','[71] stützt Linearkombinationen, Erzeugung und lineare Struktur im Modul-/Vektorraumkontext.','Modules, S. 117–172; Matrices and Linear Maps, S. 503–552.','Modules; Matrices and Linear Maps','Die Abschnitte liefern den algebraischen Rahmen für Skalarmultiplikation, Addition und Erzeugung linearer Unterräume.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (32,114,74,74,'location_paraphrase','direct','[74] stützt Linearkombinationen und daraus aufgebaute Vektorräume/Unterräume.','§1.1 Vectors and Linear Combinations, S. 2; §3.1 Spaces of Vectors, S. 123.','Vectors and Linear Combinations','Strang führt Linearkombinationen bereits als elementaren Aufbau von Vektoren und später von Räumen ein.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (33,115,82,82,'location_paraphrase','direct','[82] stützt Erzeugung, Basiskonstruktion und lineare Mannigfaltigkeiten/Unterräume.','Spaces, S. 1–54; Definition and construction of bases, S. 8; Linear manifolds, S. 14.','Definition and construction of bases; Linear manifolds','Die Fundstellen liegen im Raum-Kapitel und stützen Spann-/Erzeugungsargumente.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (34,116,71,71,'location_paraphrase','direct','[71] stützt lineare Unabhängigkeit, Basen und Dimension innerhalb linearer algebraischer Strukturen.','Modules, S. 117–172; Matrices and Linear Maps, S. 503–552.','Modules; Matrices and Linear Maps','Langs linear-algebraischer Aufbau trägt die Basis-/Dimensionsargumentation; für die didaktische Explikation sind Strang/Halmos direkter.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (35,117,74,74,'location_paraphrase','direct','[74] stützt ausdrücklich lineare Unabhängigkeit, Basis und Dimension.','§3.4 Independence, Basis and Dimension, S. 164; §3.5 Dimensions of the Four Subspaces, S. 181.','Independence, Basis and Dimension','Diese Fundstelle ist die direkte Referenz für den Kern von 3.2.6.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (36,118,82,82,'location_paraphrase','direct','[82] stützt Definition/Konstruktion von Basen und die endlichdimensionale Raumstruktur.','Spaces, S. 1–54; Definition and construction of bases, S. 8.','Definition and construction of bases','Halmos liefert eine klassische Quelle für Basen als vollständige, nichtredundante lineare Beschreibung.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (37,119,71,71,'location_paraphrase','direct','[71] stützt Matrixdarstellung linearer Abbildungen und damit die Basisabhängigkeit von Koordinatenrepräsentationen.','Matrices and Linear Maps, S. 503–552.','Matrices and Linear Maps','Die Darstellung linearer Maps durch Matrizen liefert den algebraischen Rahmen für Koordinaten- und Basiswechsel.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (38,120,74,74,'location_paraphrase','direct','[74] stützt die Matrix eines linearen Operators und die Wahl bzw. Suche einer geeigneten Basis.','§8.2 The Matrix of a Linear Transformation, S. 411; §8.3 The Search for a Good Basis, S. 421.','The Matrix of a Linear Transformation; The Search for a Good Basis','Strang trennt lineare Transformation und Matrixdarstellung und behandelt die Basiswahl explizit.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (39,121,76,76,'location_paraphrase','partial','[76] stützt den abstrakten Spektralbegriff eines Operators, nicht jedoch als primäre Quelle die elementare Basiswechselmatrix.','Kap. VI Bounded Operators, §3 The Spectrum, S. 188 ff.; Kap. VII The Spectral Theorem, S. 221 ff.','The Spectrum; The Spectral Theorem','Reed/Simon stützen die operatorische/spektrale Invarianzebene; die konkrete Ähnlichkeitstransformation sollte primär mit Strang/Lang/Halmos belegt werden.',NULL,'https://books.google.com/books?id=bvuRuwuFBWwC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (40,122,82,82,'location_paraphrase','direct','[82] stützt den Basiswechsel und dessen Einfluss auf Matrixdarstellungen.','Change of basis, S. 63; Transformations, S. 55–117.','Change of basis','Halmos besitzt einen ausdrücklich ausgewiesenen Abschnitt zum Basiswechsel.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (41,123,71,71,'location_paraphrase','direct','[71] stützt Determinanten im Kontext von Matrizen und linearen Abbildungen.','Matrices and Linear Maps, S. 503–552; darin Abschnitt Determinants (ab etwa S. 511 gemäß Inhaltsgliederung).','Matrices and Linear Maps; Determinants','Lang behandelt Determinanten innerhalb des linearen Abbildungs- und Matrixkapitels.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (42,124,74,74,'location_paraphrase','direct','[74] stützt Determinanteneigenschaften, Kofaktorentwicklung, Inversen und Volumenskalierung.','Kap. 5 Determinants, S. 247 ff.; §5.1 S. 247; §5.2 S. 258; §5.3 Cramer’s Rule, Inverses, and Volumes, S. 273.','Determinants; Inverses, and Volumes','Die Kapitelstruktur deckt die in 3.2.8 behandelten algebraischen und geometrischen Bedeutungen der Determinante direkt ab.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (43,125,82,82,'location_paraphrase','direct','[82] stützt Determinanten und deren Verbindung zur Spektralterminologie.','Determinants and the spectral terminology, S. 77; Transformations, S. 55–117.','Determinants and the spectral terminology','Halmos verknüpft Determinanten mit der Struktur linearer Transformationen.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (44,126,71,71,'location_paraphrase','direct','[71] stützt Rang, Matrixdarstellungen und lineare Abbildungen.','Matrices and Linear Maps, S. 503–552; Rangabschnitt im Anfang dieses Kapitels.','Matrices and Linear Maps','Lang behandelt Rang und lineare Abbildungen in demselben Kapitel und stützt damit Rang-/Bildargumente.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (45,127,74,74,'location_paraphrase','direct','[74] stützt Nullraum, Lösbarkeit, Rang und Dimension der fundamentalen Unterräume.','§3.2 The Nullspace of A, S. 135; §3.3 The Complete Solution to Ax=b, S. 150; §3.5 Dimensions of the Four Subspaces, S. 181.','The Nullspace of A; Dimensions of the Four Subspaces','Diese Fundstellen stützen Kern/Nullraum, Rang, Bild-/Spaltenraum und lineare Gleichungssysteme.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (46,128,82,82,'location_paraphrase','direct','[82] stützt Range und Null Space einer linearen Transformation.','Range and null space of a linear transformation, S. 69.','Range and null space','Halmos besitzt eine direkte Fundstelle zu Bild/Range und Kern/Nullspace.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (47,129,71,71,'location_paraphrase','direct','[71] stützt Eigenwerte/Eigenvektoren, charakteristisches Polynom und die Darstellung eines Endomorphismus.','Representation of One Endomorphism, S. 553–570; charakteristisches Polynom innerhalb dieses Kapitels.','Representation of One Endomorphism','Das Kapitel behandelt die spektralen Eigenschaften eines einzelnen linearen Endomorphismus.',NULL,'https://link.springer.com/book/10.1007/978-1-4613-0041-0',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (48,130,74,74,'location_paraphrase','direct','[74] stützt Eigenwerte, Eigenvektoren und den Übergang zur Diagonalisierung.','§6.1 Introduction to Eigenvalues, S. 288; §6.2 Diagonalizing a Matrix, S. 304.','Introduction to Eigenvalues','Die Fundstellen sind die direkte Referenz für Eigenwertgleichung, Eigenrichtungen und Diagonalisierbarkeitsfragen.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (49,131,82,82,'location_paraphrase','direct','[82] stützt spektrale Terminologie und die Eigenstruktur linearer Transformationen.','Determinants and the spectral terminology, S. 77; Transformations, S. 55–117.','Determinants and the spectral terminology','Halmos verknüpft Determinanten und spektrale Terminologie innerhalb der Theorie linearer Transformationen.',NULL,'https://books.google.com/books/about/Finite_Dimensional_Vector_Spaces.html?id=sWZMZi1LtMUC',NULL,'publisher','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (50,132,74,74,'location_paraphrase','direct','[74] stützt Diagonalisierung, symmetrische Matrizen und die orthogonale Eigenvektorzerlegung.','§6.2 Diagonalizing a Matrix, S. 304; §6.4 Symmetric Matrices, S. 338.','Diagonalizing a Matrix; Symmetric Matrices','Die beiden Abschnitte tragen die Diagonalisierbarkeit und den endlichdimensionalen Spektralsatz für reelle symmetrische Matrizen.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (51,133,74,74,'location_paraphrase','direct','[74] stützt Skalarprodukt/Dot Product, Norm/Länge, Orthogonalität, Projektionen und Gram-Schmidt.','§1.2 Lengths and Dot Products, S. 11; §4.1 Orthogonality, S. 194; §4.2 Projections, S. 206; §4.4 Orthonormal Bases and Gram-Schmidt, S. 233.','Lengths and Dot Products; Projections; Orthonormal Bases and Gram-Schmidt','Die Fundstellen entsprechen unmittelbar den Definitionen und Verfahren von 3.2.12.',NULL,'https://math.mit.edu/~gs/linearalgebra/ila5/index.html','https://math.mit.edu/~gs/linearalgebra/ila5/linearalgebra5_TOC.pdf','author_university','verified','location_only','2026-08-29',NULL);
INSERT INTO `source_research_evidence` (`evidence_id`,`source_usage_id`,`canonical_source_id`,`canonical_citation_number`,`evidence_mode`,`support_fit`,`claim_supported`,`exact_location`,`text_anchor`,`paraphrased_evidence`,`verbatim_excerpt`,`source_url`,`verification_url`,`source_class`,`verification_status`,`copyright_status`,`accessed_on`,`notes`) VALUES (52,134,84,84,'location_paraphrase','direct','[84] stützt Skalarprodukte/Normen, Gram-Schmidt, orthogonale Komplemente, orthogonale Operatoren, Projektionen und Spektralsatz.','Kap. 6 Inner Product Spaces: §6.1 Inner Products and Norms; §6.2 Gram-Schmidt Orthogonalization Process and Orthogonal Complements; §6.5 Unitary and Orthogonal Operators; §6.6 Orthogonal Projections and the Spectral Theorem.','Inner Product Spaces','Pearsons Inhaltsverzeichnis deckt die gesamte in 3.2.12 benötigte Struktur direkt ab.',NULL,'https://www.pearson.com/en-us/subject-catalog/p/Friedberg-Linear-Algebra-Subscription-5th-Edition/P200000006185/9780137515424',NULL,'publisher','verified','location_only','2026-08-29',NULL);

INSERT INTO `citation_resolutions`
(`citation_occurrence_id`,`original_citation_number`,`canonical_source_id`,`canonical_citation_number`,`resolution_type`,`resolution_reason`,`verification_status`)
SELECT
 co.citation_occurrence_id,
 co.source_citation_number,
 CASE
   WHEN ds.section_code='3.2.3' AND co.source_citation_number=10 THEN 74
   WHEN ds.section_code='3.2.3' AND co.source_citation_number=13 THEN 76
   ELSE co.source_id
 END,
 CASE
   WHEN ds.section_code='3.2.3' AND co.source_citation_number=10 THEN 74
   WHEN ds.section_code='3.2.3' AND co.source_citation_number=13 THEN 76
   ELSE co.source_citation_number
 END,
 CASE
   WHEN ds.section_code='3.2.3' AND co.source_citation_number IN (10,13) THEN 'replaced'
   WHEN co.source_id IS NOT NULL THEN 'same'
   ELSE 'unresolved'
 END,
 CASE
   WHEN ds.section_code='3.2.3' AND co.source_citation_number=10 THEN 'Vorläufige Literaturziffer [10] wird durch [74] Strang ersetzt.'
   WHEN ds.section_code='3.2.3' AND co.source_citation_number=13 THEN 'Vorläufige Literaturziffer [13] wird durch [76] Reed/Simon ersetzt.'
   WHEN co.source_id IS NOT NULL THEN 'Aktuelle Literaturziffer bleibt kanonisch.'
   ELSE 'Keine kanonische Quelle auflösbar.'
 END,
 CASE
   WHEN (ds.section_code='3.2.3' AND co.source_citation_number IN (10,13)) OR co.source_id IS NOT NULL THEN 'verified'
   ELSE 'needs_review'
 END
FROM citation_occurrences co
JOIN dissertation_sections ds ON ds.section_id=co.section_id;

INSERT INTO `citation_evidence_links`
(`citation_occurrence_id`,`evidence_id`,`link_status`,`notes`)
SELECT
 co.citation_occurrence_id,
 e.evidence_id,
 CASE
   WHEN sua.original_citation_number IN (10,13) THEN 'replacement_match'
   WHEN e.support_fit='partial' THEN 'partial_support'
   ELSE 'section_source_match'
 END,
 CONCAT('Zuordnung über Abschnitt ',ds.section_code,
        ' und ursprüngliche Literaturziffer [',co.source_citation_number,
        ']; kanonische Quelle [',e.canonical_citation_number,'].')
FROM citation_occurrences co
JOIN dissertation_sections ds ON ds.section_id=co.section_id
JOIN source_usage su ON su.section_id=co.section_id
JOIN source_usage_audit sua ON sua.usage_id=su.usage_id
  AND sua.original_citation_number=co.source_citation_number
JOIN source_research_evidence e ON e.source_usage_id=su.usage_id;
